    "expr1": eval_expr(Sum(sin(n), (n, 1, oo))),
    "expr2": eval_expr(Sum(sin(n)**2 + cos(n)**2 - 1, (n, 1, oo))),
    "expr3": eval_expr(Sum(sin(pi*n), (n, 1, oo))),
}

# Convert to a flat, structured record for the tool
probe("expr1.is_convergent", results["expr1"])
probe("expr2.is_convergent", results["expr2"])
probe("expr3.is_convergent", results["expr3"])

